insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('fiscal', 'beginner', 'module', 'm01-what-a-fiscal-regime-is', 1, 'What is a fiscal regime, as this engine represents one?', '["Whatever the jurisdiction''s fiscal code contains, since each template is a reading of the statute it is named for and the engine executes that reading.", "The four fields together with a signature bonus and a state participation share, which the templates carry as separate entries beside the tax block.", "Four fields on one object: a royalty, a cost recovery limit, a profit split, and a tax block holding cit, rrt, minTax and an optional rrtUpliftPct.", "A royalty and a tax, with the cost recovery limit and the profit split supplied by the project inputs rather than by the regime."]'::jsonb, 2, 'Nothing else exists. A regime that needs an instrument outside those four cannot be expressed in this sandbox at all.'),
  ('fiscal', 'beginner', 'module', 'm01-what-a-fiscal-regime-is', 2, 'A regime sets cit and rrt and omits rrtUpliftPct entirely. What uplift does the run charge?', '["20 percent, the documented default the engine substitutes whenever the field is absent.", "Zero, because a field that was never supplied cannot grant relief, so the resource rent tax falls on the profit share itself.", "The same figure as rrt, since the uplift is written as a fraction of the resource rent tax rate it belongs to.", "None, and the run refuses the regime until an uplift is supplied for it."]'::jsonb, 0, 'The uplift is optional in the object and defaults to 20, so a template that says nothing about it is not running without one.'),
  ('fiscal', 'beginner', 'module', 'm01-what-a-fiscal-regime-is', 3, 'Nigeria - PIA (2021) and Generic Royalty/Tax both carry CIT 30 percent, RRT 0 percent and minimum tax 0 percent, yet on the Designer''s default project the contractor keeps 406.2057 million USD under one and 986.7327 million USD under the other. What opened that gap?', '["A heavier tax bill under the PIA terms, which totals 422.8854 million USD over the life against 174.0882 million USD for the Generic terms.", "The other three fields, a cost recovery limit of 80 percent instead of 100 and an R factor split of 60, then 40, then 30 percent instead of a flat 100 percent to the contractor.", "A larger royalty under the PIA slider, which collects 335.8660 million USD against the 268.6928 million USD the Generic rate collects.", "Different sales, since the PIA line is run against a lower price deck than the Generic line is."]'::jsonb, 1, 'The PIA line pays the smaller tax of the two, 174.0882 million USD against 422.8854, and the smaller royalty, 268.6928 against 335.8660. A tax rate quoted on its own predicts nothing.'),
  ('fiscal', 'beginner', 'module', 'm01-what-a-fiscal-regime-is', 4, 'Six templates are run on the published test project. What does the total revenue column read down those six lines?', '["It falls as the royalty rate rises, since royalty is charged on the top line before anything else is deducted from it.", "It moves by a few million USD, because each template recovers cost at a different limit and cost recovery is netted against sales.", "It reads 2686.9277 million USD, which is the revenue figure every comparison in this sandbox reports.", "7001.1938 million USD on every one of them, because a regime touches neither production nor price."]'::jsonb, 3, '2686.9277 million USD is the default project''s constant. Whichever project is loaded, the revenue column is the same on all six lines, so any spread in the answer is the regime.'),
  ('fiscal', 'beginner', 'module', 'm01-what-a-fiscal-regime-is', 5, 'Which project input shortens the sandbox horizon below 25 years?', '["None of them. PROJECT_LIFE is 25 rows and the engine returns 25 rows for every regime and every project.", "The economic limit, reached in the year opex first exceeds gross revenue, after which the remaining rows are dropped from the totals.", "The price deck, whose last dated point closes the profile in the year that point falls in.", "A steep decline, which ends the profile once the rate has fallen far enough below the initial rate."]'::jsonb, 0, 'There is no input anywhere that changes 25 to another number, which is why year 25 of the default project still produces 0.291148 million bbl.'),
  ('fiscal', 'beginner', 'module', 'm01-what-a-fiscal-regime-is', 6, 'The published case that puts capex of 20000 on the test project reports payback year null and payout year null. What does that say about its 25 rows?', '["The engine truncated the run in the year the pool was judged unrecoverable, so the totals cover fewer than 25 rows.", "The rows after the loss were computed but left out of government take, which is why that figure stops at 875.1492 million USD.", "Nothing stopped. All 25 were computed, taxed and counted into the totals, and null records only that cumulative contractor net cash flow never rose above zero.", "The project was abandoned inside the model, and the abandonment charge is the closing pool of 15724.0151 million USD."]'::jsonb, 2, 'Reading null as a stop is how a reader ends up quoting a 25 year royalty stream as a short one. Total contractor net cash flow on that case is -15724.0151 million USD.'),
  ('fiscal', 'beginner', 'module', 'm01-what-a-fiscal-regime-is', 7, 'On that same 20000 capex case the treasury collects 875.1492 million USD. Which instrument delivered it?', '["The minimum tax, which floors the government at a percent of gross revenue in any year the profit share collapses.", "Royalty alone, since total profit oil and total tax are both 0.0000 million USD there.", "Cost recovery, which hands the unrecovered pool back to the state once the horizon ends without clearing it.", "Resource rent tax charged on the negative cash flow, against the annual capital uplift the tax block carries."]'::jsonb, 1, 'No abandonment and no economic limit exist to stop the field, so it produces for 25 years and pays royalty on total revenue of 7001.1938 million USD while losing money.'),
  ('fiscal', 'beginner', 'module', 'm01-what-a-fiscal-regime-is', 8, 'A template field reads 18.75 and the derived rate column beside the royalty reads 0.187500. How do the two relate?', '["The column is the rate after the cost recovery limit has been applied to it, which is why it prints so much smaller than the field does.", "The field is quoted on gross revenue and the column on revenue after royalty, so the two differ by the royalty itself.", "The column is a rate of 0.187500 percent, which is what a royalty of 50.9979 million USD on 271.9889 million USD of revenue works out at.", "They are one instrument in two conventions, a percent and a ratio."]'::jsonb, 3, 'A rate of 0.187500 percent charged on gross revenue of 271.9889 million USD could never produce the 50.9979 million USD the royalty column prints.'),
  ('fiscal', 'beginner', 'module', 'm01-what-a-fiscal-regime-is', 9, 'Year 1 gross revenue on the Designer''s default project prints as 271.9889. In what unit?', '["United States dollars, which makes the year 1 capex charge of 500.0000 a rounding error.", "Millions of United States dollars, so 271.9889 million USD against a capex row of 500.0000 million USD.", "Millions of barrels of oil equivalent, converted at 6000 scf per barrel before the deck price for the year is applied.", "Millions of United States dollars on a real basis, restated to year 1 money by the deflator the sandbox carries."]'::jsonb, 1, 'Money is millions of USD everywhere in the ledger, printed to four decimals and quoted as printed. A reader who carries 271.9889 as USD believes the project pays back instantly.'),
  ('fiscal', 'beginner', 'module', 'm01-what-a-fiscal-regime-is', 10, 'What is the 6000 scf per barrel conversion used for in this model?', '["The variable half of opex, which is charged in USD per boe, and nothing else.", "Gross revenue, where the three streams are priced as one boe total.", "The royalty base, charging gas and NGL at the oil rate.", "The R factor, whose cumulative revenue is expressed in boe before it is divided by cumulative cost."]'::jsonb, 0, 'Revenue prices each stream at its own deck point. The engine writes the boe conversion as a multiply by 1000 and a divide by 6000, and the variable opex rate is the only place it is needed.'),
  ('fiscal', 'beginner', 'module', 'm01-what-a-fiscal-regime-is', 11, 'Year 1 of the default project shows oil at 3.650000 and gas at 0.018250. Is the gas negligible?', '["Yes, and the published case that adds gas and NGL to the default project confirms it by leaving total revenue unchanged.", "Yes, since a stream contributing under one percent of the volume is dropped from the boe total the variable opex is charged on.", "The comparison cannot be made from those two figures, because oil is in million bbl and gas is in million Mscf.", "No, because the gas column has already been converted to barrels of oil equivalent at 6000 scf per barrel."]'::jsonb, 2, 'The two columns are not on the same axis at all. The oil and NGL columns are million bbl and the gas column is million Mscf.'),
  ('fiscal', 'beginner', 'module', 'm01-what-a-fiscal-regime-is', 12, 'Why is subtracting the two printed endpoints of a derived column and matching the printed difference a bad check?', '["The printed endpoints belong to different rows of the ledger, while a derived difference is only ever computed within one row.", "A derived column is computed at full precision and then rounded, and its endpoints are rounded too, so a printed pair of 79.2711 and 79.4678 carries a printed climb of 0.1968.", "A derived column is an estimate the engine never returns, so it carries no defined precision to check anything against.", "Derived columns print to six decimals and returned columns to four, so the two can never be put in the same subtraction."]'::jsonb, 1, 'Both figures are correct and the hand subtraction is off by one in the last place. The default project''s Generic Royalty/Tax pair does the same thing, printing 51.2558 and 41.0660 against a climb of -10.1897.'),
  ('fiscal', 'beginner', 'module', 'm01-what-a-fiscal-regime-is', 13, 'What separates a million USD in year 25 from a million USD in year 1 here?', '["An escalation carried by the price deck past its last dated point.", "A real basis, so every row prints in year 1 money.", "A valuation date the rows are restated against.", "Only the discount exponent, since there is no inflation and no deflator anywhere."]'::jsonb, 3, 'The units refuse to carry a currency year. A row is a year and the year is its own discount exponent, and nothing else distinguishes the two.'),
  ('fiscal', 'beginner', 'module', 'm01-what-a-fiscal-regime-is', 14, 'The engine header names a single source of truth for Nigerian fiscal math. What is this model for?', '["Comparing the shape of regimes against each other, with the Petroleum Economics Studio engine holding the fiscal truth.", "Assessing a Nigerian liability under the Petroleum Industry Act, which is why the template set carries a PIA entry at all.", "Producing a filing figure, once a template has been reconciled against the Petroleum Economics Studio engine on the same project.", "Replacing that engine for screening work, since the two agree on a total government take of 1339.2784 million USD."]'::jsonb, 0, 'A template named for a jurisdiction is a caricature in six numbers, useful for asking which instrument moved which result and unfit for filing anything.'),
  ('fiscal', 'beginner', 'module', 'm01-what-a-fiscal-regime-is', 15, 'A term sheet carries a signature bonus, a domestic supply obligation and a state participation share. How are the three entered?', '["The bonus goes into a capex bucket, the obligation into the variable opex rate, and the participation share into the contractor split.", "Each becomes a tier on the profit split, the one field taking more than one entry.", "They are not. A regime needing any of them cannot be expressed in this sandbox at all.", "They ride on the template''s description string into government take."]'::jsonb, 2, 'There is no signature bonus, no domestic supply obligation, no state participation and no flare penalty. Four fields, and the ledger they act on, are the whole of it.'),
  ('fiscal', 'beginner', 'module', 'm02-the-project-before-the-regime', 1, 'The Designer''s default project declares oil at 10000 bbl/d declining 10 percent a year, and year 1 comes back as 3.650000 million bbl. Why is there no decline in that first figure?', '["A mid year convention takes half a year of decline in year 1, and at a 10 percent decline the half year rounds away before the figure is printed.", "Year 1 is a stub the engine leaves flat, and the exponential starts from the first full year of production after it.", "The decline is applied after the year is booked, so year 1 is the initial rate times 365 days and the first reduction lands in year 2.", "The declared decline is nominal rather than effective, so nothing is lost in year 1 and the later years lose more."]'::jsonb, 2, 'The check is arithmetic you can do in your head: year 1 in million bbl is the daily rate times 365 divided by one million, exactly. ODIDI at 8000 bbl/d gives 2.920000 the same way.'),
  ('fiscal', 'beginner', 'module', 'm02-the-project-before-the-regime', 2, 'generateProductionProfile is not exported. How are the annual volumes recovered from the engine?', '["By reading them out of the returned object, which records each stream beside the revenue that stream produced in the year.", "By dividing the printed gross revenue by the applied oil price, which the engine reports in a column of its own.", "By rebuilding them from the declared rate and decline, since no exported quantity depends on volume alone.", "By a probe: royalty zero, a 100 percent limit, a flat 100 percent split, every tax at zero, two streams zeroed and the survivor priced at 1.0."]'::jsonb, 3, 'grossRevenue then returns that stream''s annual volume divided by one million, which is why the oil and NGL columns read million bbl and the gas column million Mscf.'),
  ('fiscal', 'beginner', 'module', 'm02-the-project-before-the-regime', 3, 'Year 25 of the default project still produces 0.291148 million bbl of oil and still pays 11.5851 million USD of opex. What ends the field?', '["The fixed horizon of 25 rows and nothing else, because the sandbox carries no economic limit.", "The year opex overtakes gross revenue, which on this project is year 25 at 11.5851 against 24.3216 million USD.", "The last dated point on the price deck, since no revenue can be computed for a year the deck does not reach.", "Exhaustion of the profile, an exponential decline having taken the rate to zero by the end of the horizon."]'::jsonb, 0, 'Year 25 pays 11.5851 million USD of opex against 24.3216 million USD of revenue, so it happens to pay. Nothing would have stopped it if it did not.'),
  ('fiscal', 'beginner', 'module', 'm02-the-project-before-the-regime', 4, 'Between year 1 and year 25 the default gas column falls from 0.018250 to 0.002467 while the NGL column falls from 0.547500 to 0.025466. What does that show?', '["Gas is held up late in life by the deck, whose gas points keep stepping while the liquid points have run out.", "Each stream declines at its own rate, and the 8 percent gas stream keeps a larger fraction of itself than the 12 percent NGL stream.", "The engine floors a stream once it falls far enough below its initial rate, which is what flattens the gas tail.", "NGL is produced as a yield off the gas stream, so it has to fall faster than the gas it comes from."]'::jsonb, 1, 'Three independent exponentials. ODIDI shows the same thing harder, gas at 9 percent going from 0.014600 to 0.001518 while NGL at 15 percent goes from 0.328500 to 0.006646.'),
  ('fiscal', 'beginner', 'module', 'm02-the-project-before-the-regime', 5, 'The published test project declares gas at 0 Mscf/d and NGL at 0 bbl/d, each with a decline of 0 percent. What does the engine do with the two streams?', '["It drops both and returns a single stream project, which is how the test project reaches total revenue of 7001.1938 million USD on one declining oil stream.", "It generates a column of zeros for all 25 years, contributing 0.0000 to revenue and no boe to opex, which is not the same as skipping them.", "It reads a decline of 0 percent as a flat stream held at its initial rate, so both columns are constant instead of declining.", "It refuses the project, since a stream must carry a positive initial rate before any decline can be applied to it."]'::jsonb, 1, 'A zero stream is present and priced. The test project is a useful control precisely because those two columns are zeros rather than absences.'),
  ('fiscal', 'beginner', 'module', 'm02-the-project-before-the-regime', 6, 'What relationship does the sandbox model between the oil, gas and NGL streams?', '["A gas oil ratio, which ties the gas rate to the oil rate declared for the project and declines along with it.", "A condensate yield, so the NGL volume is computed off the gas volume rather than from an initial rate of its own.", "A shrinkage and fuel deduction, taken off the gas stream before it reaches the revenue sum or the boe sum.", "None. Three independent exponentials, summed once in revenue and again in boe."]'::jsonb, 3, 'There is no gas oil ratio, no yield, no shrinkage and no flare deduction. Each stream carries only an initial rate and a decline.'),
  ('fiscal', 'beginner', 'module', 'm02-the-project-before-the-regime', 7, 'The default deck prices oil at 70 in year 1 and 75 in year 5. What price is applied in years 2, 3 and 4?', '["70.000000 USD per bbl in each of them, because getPriceForYear holds the last point reached and never interpolates.", "A straight line drawn between the two dated points, so that the three years climb steadily from 70.000000 towards 75.000000 USD per bbl.", "75.000000 USD per bbl, since the next dated point is known and the engine prices forward to it.", "The average of the two dated points, held flat until the year 5 point takes over from it."]'::jsonb, 0, 'The whole move from 70.000000 to 75.000000 arrives in a single row. A deck is a staircase, and nothing between two points is interpolated.'),
  ('fiscal', 'beginner', 'module', 'm02-the-project-before-the-regime', 8, 'The default deck''s last dated point is year 10 at 80 USD per bbl. What is applied in year 25?', '["A price grown from 80.000000 at the project discount rate of 10 percent a year, which is the escalation this model applies.", "Nothing, the deck having run out and the revenue column ending with its last dated point.", "80.000000 USD per bbl, unchanged, because the engine does not escalate past the last point on a deck.", "The year 10 price adjusted for the fall in volume, so that the revenue column declines smoothly to the end."]'::jsonb, 2, 'Sixteen consecutive years sit at 80.000000 USD per bbl. A reader expecting annual escalation carries a growing shortfall from year 10 to year 25 and cannot find it, because no output column reports a price.'),
  ('fiscal', 'beginner', 'module', 'm02-the-project-before-the-regime', 9, 'ODIDI steps from 45 to 65 USD per bbl at year 6 and its revenue rises from 76.1939 to 93.9859 million USD. The default project steps from 70 to 75 at year 5 and its revenue falls from 197.5024 to 191.1513. Why the opposite signs?', '["The default step lands in a year where the deck also lowers its gas and NGL points, which cancels the gain on oil.", "The size of the step against the size of the decline. A 5 USD step does not outrun a 10 percent oil decline, and a 20 USD step does outrun a 14 percent one.", "ODIDI''s step is the second point on its deck and the default step is the third, and only a second point is applied in full.", "Volume rose in ODIDI at year 6, a price step lifting the rate the profile is generated from."]'::jsonb, 1, 'Every ODIDI stream fell in year 6. The whole of the rise from 76.1939 to 93.9859 million USD is the deck.'),
  ('fiscal', 'beginner', 'module', 'm02-the-project-before-the-regime', 10, 'Which column of the returned ledger reports the price the engine used for a year?', '["The deck column, which the engine copies out of the project inputs into every row of the ledger it returns.", "The implied rate column, which carries the price the royalty tier for that year was selected on.", "The rFactor column, whose numerator is cumulative revenue and therefore the prices behind each year of it.", "None of them. The applied price is recovered by dividing revenue by volume in a single stream probe."]'::jsonb, 3, 'Nothing in the output says which deck was used, which is why a deck read wrongly produces a shortfall with no column to trace it to.'),
  ('fiscal', 'beginner', 'module', 'm02-the-project-before-the-regime', 11, 'Default project opex reads 31.0027 million USD in year 1 and 11.5851 in year 25, against a fixed figure of 10 million USD a year. What is moving?', '["The variable half, 5 USD per boe on a declining boe total, which is why the curve heads towards the fixed number.", "The fixed half, which the engine escalates through the early years and relaxes as the field matures.", "The regime, since opex enters the cost pool and the pool is drawn down over the life of the field.", "The deck, because the variable rate is charged against revenue rather than against the barrels produced, and revenue steps at year 5."]'::jsonb, 0, 'Almost the whole of the year 25 bill of 11.5851 million USD is the fixed 10 million USD a year. The curve would only reach it if production reached zero, which the horizon ends first.'),
  ('fiscal', 'beginner', 'module', 'm02-the-project-before-the-regime', 12, 'ODIDI runs a variable rate of 4 USD per boe against the default project''s 5, yet its year 25 opex of 12.3405 million USD is above the default project''s 11.5851. How?', '["ODIDI produces more boe in year 25, its gas decline of 9 percent being slower than the default project''s 8 percent.", "ODIDI''s discount rate of 12 percent is applied to the cost columns, which lifts every year in the tail.", "By year 25 almost the whole bill is fixed, and ODIDI''s fixed figure is 12 million USD a year against 10.", "The variable rate is charged on revenue, and ODIDI''s deck prices oil at 85 USD per bbl in year 25 against 80."]'::jsonb, 2, 'ODIDI starts well below the default project, at 25.0037 million USD against 31.0027, and ends above it. The fixed half decides the tail.'),
  ('fiscal', 'beginner', 'module', 'm02-the-project-before-the-regime', 13, 'The default deck steps oil from 70 to 75 USD per bbl at year 5, and opex moves from 25.1816 to 23.6264 million USD. Why did the cost fall in a year the price rose?', '["The variable rate is charged on revenue after royalty, which fell that year even though the oil price rose.", "Opex tracks boe, and boe does not know what a barrel sold for.", "The fixed half is prorated against the deck, so a higher price lowers the fixed charge carried in the year.", "The step is applied at the end of the year, so year 5 costs are still computed at 70.000000 USD per bbl."]'::jsonb, 1, 'Opex is fixed plus the variable rate times the boe produced, divided by one million. Price enters revenue and nothing else.'),
  ('fiscal', 'beginner', 'module', 'm02-the-project-before-the-regime', 14, 'A development is to be built over three years. How is the schedule entered?', '["It is not. Capex is one sum charged to year 1, 500.0000 million USD on the default project and 420.0000 on ODIDI, and the multiplier scales the total rather than the timing.", "By splitting the three buckets, since drilling, facilities and subsea are each charged in the year the engine assigns them.", "By setting the capex multiplier below one and running the remainder as a second project, which spreads the same total.", "By lowering the multiplier to 0.7, which moves the spend later and lifts NPV to 1460.6941 million USD on the flat regime."]'::jsonb, 0, 'The sandbox refuses a capex schedule and has no field to hold one. Faking it with the multiplier changes the total and quietly answers a different question.'),
  ('fiscal', 'beginner', 'module', 'm02-the-project-before-the-regime', 15, 'Six regimes are compared on one project. What do their opex and capex columns look like?', '["They part at the cost recovery limit, which caps how much of each year''s cost the ledger admits in the first place.", "They part once the pool clears, since unrecovered cost is written back out of the opex column in the year that happens.", "They part in year 1 only, where the capex charge is netted against the royalty the regime takes off the top line.", "Identical, row for row, because nothing a government does in this model changes what the field costs."]'::jsonb, 3, 'The cost columns do not depend on the regime. Over the life the default project spends 441.4436 million USD of opex and ODIDI spends 390.2137 million USD, whichever template is loaded.'),
  ('fiscal', 'beginner', 'module', 'm03-revenue-and-royalty', 1, 'How is the gross revenue row built?', '["The three streams converted to boe at 6000 scf per barrel and then priced at the deck''s oil point for the year.", "Volumes at deck prices less the transport and processing the project declares, which is what states the row in millions of USD.", "Oil volume times the applied oil price, plus gas times its price, plus NGL times its price, all divided by one million.", "Oil at the deck price plus the gas and NGL taken at a fraction of it, the deck carrying only one dated series."]'::jsonb, 2, 'The divide by one million is what puts the ledger in millions of USD. Year 1 of the default project is 271.9889 million USD and year 25 is 24.3216.'),
  ('fiscal', 'beginner', 'module', 'm03-revenue-and-royalty', 2, 'What is the royalty charged on?', '["Gross revenue, before any cost is deducted and before anything else in the ledger happens.", "Revenue after opex, which is the netback a production sharing contract normally charges a royalty against.", "Revenue after cost recovery, so that the cost pool is served before the state takes a share of the year.", "Profit oil, royalty and the profit split being the two instruments that divide what is left once cost is met."]'::jsonb, 0, 'Year 1 of the default project pays 50.9979 million USD of royalty on 271.9889 million USD of revenue. Nothing has been deducted from the base.'),
  ('fiscal', 'beginner', 'module', 'm03-revenue-and-royalty', 3, 'The implied rate column under USA - Gulf of Mexico reads 0.187500 in year 1, in year 5 and in year 25 of the default project. What has that demonstrated?', '["That the deck holds one oil price across those years, since the implied rate would move with the price if it did not.", "That the royalty really is flat, proved from the two printed columns rather than assumed from the template field of 18.75.", "That the royalty is charged on a base declining at the same rate as revenue, which is what holds the ratio still.", "That the rate has been checked in the three years where a check is possible, the deck steps being the years where it is not."]'::jsonb, 1, 'Royalty is 50.9979 million USD on 271.9889 in year 1 and 4.5603 on 24.3216 in year 25. One rate, one base, twenty five years.'),
  ('fiscal', 'beginner', 'module', 'm03-revenue-and-royalty', 4, 'Year 1 of the default project under the Gulf of Mexico terms carries capex of 500.0000 million USD and a contractor net cash flow of -310.0117. What royalty is charged that year?', '["Nothing, since a royalty is charged on revenue after royalty and no profit oil arises in the year the capex lands.", "A reduced charge, the sandbox waiving royalty in a year that closes below zero.", "50.9979 million USD, which then enters the unrecovered cost pool and comes back to the contractor in a later year.", "50.9979 million USD, the full rate on the top line, and that is the whole of government take for the year."]'::jsonb, 3, 'A loss making year pays royalty at the same rate as the best year in the field. There is no profit oil and no tax in year 1, so government take is the royalty alone.'),
  ('fiscal', 'beginner', 'module', 'm03-revenue-and-royalty', 5, 'Which column of the returned ledger holds revenue after royalty?', '["The costRecovered column, which equals it whenever the limit is 100 percent and the pool is deep enough to absorb the whole of the year''s cost.", "The profitOil column, which is revenue after royalty once the profit split has been applied to it.", "No column does. It is the difference of two printed columns, and it is the base the cost recovery limit is a percent of.", "The grossRevenue column, the royalty being settled outside the ledger and never entering the revenue row that the recovery limit is taken on."]'::jsonb, 2, 'Under the Gulf of Mexico terms year 1 of the default project carries revenue after royalty of 220.9910 million USD, and that is the ceiling a 100 percent limit gives.'),
  ('fiscal', 'beginner', 'module', 'm03-revenue-and-royalty', 6, 'In year 1 of the default project revenue after royalty is 220.9910 million USD and the costs are capex of 500.0000 and opex of 31.0027. What does a cost recovery limit of 100 percent do?', '["Nothing, a 100 percent limit not being a limit, so the whole of the year''s cost is recovered against it.", "It binds. The ceiling of 220.9910 million USD is below the capex charge on its own, so costRecovered stops there and the pool closes at 310.0117 million USD.", "It caps recovery at 271.9889 million USD, the year''s gross revenue being what a 100 percent limit is a percent of.", "It leaves the capex in the pool untouched and recovers the opex of 31.0027 million USD, the recoverable half in a capex year."]'::jsonb, 1, 'A 100 percent limit is not the same thing as recovering everything. It binds whenever the year''s costs exceed its revenue after royalty, which a year one capex charge guarantees.'),
  ('fiscal', 'beginner', 'module', 'm03-revenue-and-royalty', 7, 'A reader takes the cost recovery ceiling as a percent of gross revenue instead. How large is the error in year 1 of the default project?', '["Exactly the royalty, 50.9979 million USD of extra recovery, which then flows into the pool, into the R factor and into every split keyed on it.", "It is immaterial at a 100 percent limit, since the ceiling binds either way in the year the capex lands.", "It is the spread between the two limits the template set uses, 80 percent against 100, applied to the year''s revenue.", "It cancels in the totals, a larger recovery in year 1 leaving a smaller pool for the years that follow it."]'::jsonb, 0, 'The tell is worth memorising: if a cost recovery ceiling ever equals gross revenue, the wrong base has been used, because royalty is always taken first.'),
  ('fiscal', 'beginner', 'module', 'm03-revenue-and-royalty', 8, 'Angola - Deepwater PSC charges a royalty of 0 percent and collects 0.0000 million USD on the default project, yet its contractor keeps 545.1955 million USD against 980.9313 under the Gulf of Mexico terms. Why?', '["Its production is lower, the Angola template being run on a deepwater profile rather than on the Designer''s default project.", "Its royalty is collected later as an additional entitlement, which the template description records and the run applies at the end.", "Its CIT of 25 percent is charged on gross revenue rather than on the contractor profit share, which is the harsher base.", "Its other three fields are hard: cost recovery capped at 50 percent, a tiered profit split, and RRT at 50 percent."]'::jsonb, 3, 'A low headline rate is not a soft regime. The template with no royalty at all is the harsher of the two here.'),
  ('fiscal', 'beginner', 'module', 'm03-revenue-and-royalty', 9, 'Nigeria - PIA (2021) collects total royalty of 268.6928 million USD on the default project and 700.1194 on the test project, and Brazil - Concession collects exactly the same on both. How does a slider match a flat 10 percent?', '["The engine averages a sliding scale over the life of the field and charges one mean rate, which for tiers of 7.5 and 10 percent works out at 10 percent on both decks.", "The slider keys on the first dated point of the deck, which is above 50 USD per bbl on both projects, and that point then fixes the rate for the whole of the 25 year run.", "Every applied price on both decks is above the 50 USD per bbl threshold, so the slider sits in its 10 percent tier in every year and never slides.", "A sliding royalty falls back to the flat rate of the nearest template whenever its two tiers straddle the deck."]'::jsonb, 2, 'The default deck prices oil at 70, 75 and 80 USD per bbl and the test deck at 80. A sliding instrument that never slides is a flat one, and whether it slides is a property of the deck.'),
  ('fiscal', 'beginner', 'module', 'm03-revenue-and-royalty', 10, 'What can move the tier a sliding royalty selects?', '["The applied oil price for the year, and nothing else.", "The oil price or the gas price, whichever of the two streams contributed more revenue in the year being priced.", "Cumulative production, which is the variable a progressive royalty is normally keyed on in a real contract.", "The R factor, the ratio this sandbox uses to key the royalty tiers and the profit split tiers alike."]'::jsonb, 0, 'It reads the applied oil price, so anything that changes that price changes the tier as well as the revenue. Not gas, not NGL, not rate, not cumulative volume, not the R factor.'),
  ('fiscal', 'beginner', 'module', 'm03-revenue-and-royalty', 11, 'Ghana - Deepwater is described as featuring an additional oil entitlement and Brazil - Concession as carrying a special participation tax. Where do those two instruments appear in a run?', '["Both are charged after tax, as a further deduction from the contractor''s profit share in the years their descriptions cover.", "Nowhere as instruments. Ghana''s entitlement is expressed as an R factor split and Brazil''s windfall as RRT at 40 percent, and only the four fields execute.", "Ghana''s entitlement is the cost recovery limit of 90 percent and Brazil''s participation tax is the CIT of 34 percent.", "Both are carried as extra tiers, Ghana''s on the profit split and Brazil''s on the royalty, which is why the two read as tiered."]'::jsonb, 1, 'The description is prose. Six fields are executed, and a template cannot hold an instrument that has no field.'),
  ('fiscal', 'beginner', 'module', 'm03-revenue-and-royalty', 12, 'Three of the six templates take a flat 100 percent of profit oil to the contractor and recover cost at 100 percent. What are the other three?', '["Tiered on the oil price, at those same three limits, a sharing regime keying its split on the price it sells at.", "Flat splits below 100 percent, the difference between the split and 100 being the government''s share of profit oil.", "Concessions as well, differing only in the royalty rates of 7.5, 5 and 0 percent that the three of them carry.", "Tiered on the R factor, with cost recovery capped at 80, 90 and 50 percent."]'::jsonb, 3, 'Those are the templates where the middle columns do real work, because an unrecovered balance has somewhere to accumulate and the contractor''s share changes as the field matures.'),
  ('fiscal', 'beginner', 'module', 'm03-revenue-and-royalty', 13, 'Which template collects the most royalty on the default project, and what does that predict about its contractor?', '["USA - Gulf of Mexico at 503.7989 million USD, which leaves that contractor the least cash of the six at 406.2057 million USD.", "Generic Royalty/Tax at 335.8660 million USD, since 12.5 percent is the highest flat rate anywhere in the list.", "USA - Gulf of Mexico at 503.7989 million USD, and it predicts nothing: that contractor keeps 980.9313 million USD, more than four of the other five.", "Nigeria - PIA (2021) at 268.6928 million USD, a slider in its top tier outcollecting every flat rate in the set."]'::jsonb, 2, '406.2057 million USD is the PIA contractor, under a royalty of 268.6928 million USD. The royalty ranking and the contractor ranking are not the same ranking.'),
  ('fiscal', 'beginner', 'module', 'm03-revenue-and-royalty', 14, 'What has been deducted from the 271.9889 million USD on the default project''s year 1 top line?', '["A quality differential against the marker the deck''s dated points are quoted on for each of the three streams.", "Nothing at all. No transport, no processing, no quality bank, no marketing fee and no working interest adjustment.", "A marketing fee, taken before the royalty base is set so that the state and the contractor share the cost of the sale.", "The gas and NGL streams, which are carried below the oil line and added back before the royalty is charged on it."]'::jsonb, 1, 'It is volumes at deck prices and nothing else, and that number is exactly the royalty base.'),
  ('fiscal', 'beginner', 'module', 'm03-revenue-and-royalty', 15, 'Two regimes in one comparison report different total revenue. What has happened?', '["They were not run on the same project, because a regime touches neither production nor price.", "One of them charged its royalty on the top line, which is deducted from the revenue column before that column prints.", "One of them ran at a different cost recovery limit, so a different part of the top line reached the revenue total.", "Their decks stepped in different years, a deck being a regime setting."]'::jsonb, 0, 'Total revenue reads 2686.9277 million USD down all six lines of a default project comparison and 7001.1938 down all six of a test project comparison. It is a constant, and that is what makes the spread legible.'),
  ('fiscal', 'beginner', 'module', 'm04-the-concession-ledger', 1, 'Add contractor net cash flow and government take on one row of a ledger this engine returns. What does the pair equal?', '["Gross revenue less opex less capex, in every year, under every one of the six templates.", "Gross revenue less opex less capex, less the movement in the unrecovered cost pool, because cost that was not recovered in the year reached neither party.", "Gross revenue less royalty, because the royalty is settled off the top before the cascade begins and belongs to neither of the two takes.", "Gross revenue, since every dollar the field sold is assigned in the year to the contractor or to the state and nothing else is done with it."]'::jsonb, 0, 'Year 1 of the default project reads -259.0138 for both sums under the Gulf of Mexico terms at a 100 percent limit and under Angola at 50 percent, though the closing pools are 310.0117 and 395.0083.'),
  ('fiscal', 'beginner', 'module', 'm04-the-concession-ledger', 2, 'Angola recovers cost at a 50 percent limit and closes year 1 of the default project with 395.0083 still in the pool, yet its two takes add to the same -259.0138 as a regime that recovered everything. Why does the unrecovered balance open no gap?', '["The engine writes the shortfall off against the state''s share of profit oil in the same year, so the pair is restored on the government side of the row.", "The limit is taken on revenue after royalty, and royalty sits outside the identity, so the shortfall cancels against the royalty column instead.", "An unrecovered balance is not a cash movement. It stays in the pool and becomes somebody''s profit oil in a later year.", "The contractor is credited with the shortfall as a receivable in the year it arises, and that receivable is carried inside contractor net cash flow."]'::jsonb, 2, 'Cost recovered plus profit oil is revenue after royalty in every year, so recovery and royalty both cancel out of the sum. Swept over 450 rows the largest disagreement is 1.7053e-13.'),
  ('fiscal', 'beginner', 'module', 'm04-the-concession-ledger', 3, 'The engine''s own header records that this identity used to fail before the E1 pass. What was wrong?', '["Royalty was charged on revenue after cost recovery rather than on gross revenue, so the two takes overstated every year by the size of the royalty column.", "Recovered cost was subtracted from profit oil and then dropped, credited to neither side, so the two takes fell short of revenue less cost by exactly the cost recovered.", "The unrecovered pool was discounted at the project rate before being carried forward, which quietly lost a part of the balance in each year of the life.", "Tax was charged on gross revenue instead of on the contractor''s profit share, so the government side of the row collected more than the cascade had produced."]'::jsonb, 1, 'Cost oil is now credited to the contractor and the full cost outflow enters the pool. The second defect was that opex never became recoverable at all.'),
  ('fiscal', 'beginner', 'module', 'm04-the-concession-ledger', 4, 'The Gulf of Mexico terms set the cost recovery limit at 100 percent, and year 1 of the Designer''s default project still closes with a pool of 310.0117. What did that limit actually allow?', '["Recovery of 271.9889, the whole of gross revenue, which still falls short of the year''s spending and leaves the remainder to be carried forward.", "Recovery of the year''s opex of 31.0027 and capex of 500.0000 in full, with the pool holding only what the revenue could not fund.", "Recovery of nothing at all in year 1, because the pool is seeded with the capex before any allowance against revenue is computed for the year.", "Recovery of 220.9910, the whole of revenue after royalty, against opex of 31.0027 and capex of 500.0000."]'::jsonb, 3, 'A 100 percent limit is a ceiling on revenue after royalty, not a promise to return the spend, so 310.0117 is carried into year 2.'),
  ('fiscal', 'beginner', 'module', 'm04-the-concession-ledger', 5, 'A published case runs the test project at capex 20000. Life contractor net cash flow is -15724.0151 and the closing unrecovered pool is 15724.0151. Why is it one figure with two signs?', '["The pool is charged to the contractor as a cash cost in the closing year, and that charge is what makes the two columns agree at the end of the life.", "The engine floors the pool at the size of the loss, so it is one quantity printed twice.", "Profit oil never appears, so the contractor''s life is exactly the cost that recovery could not reach.", "Royalty of 875.1492 was recovered out of the pool, which balances the two."]'::jsonb, 2, 'Total profit oil is 0.0000 and total tax is 0.0000, so the state collected royalty of 875.1492 and the contractor absorbed all the rest.'),
  ('fiscal', 'beginner', 'module', 'm04-the-concession-ledger', 6, 'From year 4 of the Gulf of Mexico ledger on the default project, costRecovered and opex are one number, 25.1816. What does that show?', '["The pool closed at 0.0000 in year 3, so the only cost left to assign is the year''s own opex.", "The limit started to bind in year 4, capping recovery at the opex figure and carrying the rest of the standing pool forward into year 5.", "Opex became recoverable in year 4, once the whole of the capex had been returned.", "Recovery moved onto a straight line schedule once the capex came back."]'::jsonb, 0, 'Year 3 recovered 167.1490 and closed the pool at 0.0000, so from year 4 the two columns cancel and the row is worth the profit share less tax.'),
  ('fiscal', 'beginner', 'module', 'm04-the-concession-ledger', 7, 'Year 1 of the Gulf of Mexico ledger reports profitOil 0.0000 beside a contractor line of -310.0117. What does the 0.0000 say about the year?', '["The year broke even, because a residual of zero is what a year that exactly covered its own costs is bound to produce in this ledger.", "Revenue after royalty of 220.9910 went entirely to cost recovery, leaving no residual for the split to act on.", "The regime assigned the whole residual to the state, which is the reason the contractor''s line is negative by the size of the capex.", "Profit oil is floored at zero and the true residual was negative by 310.0117."]'::jsonb, 1, 'Profit oil carries no opex, no capex and no tax, and this 0.0000 sits in a year that spent 500.0000 of capex.'),
  ('fiscal', 'beginner', 'module', 'm04-the-concession-ledger', 8, 'Profit oil under the Gulf of Mexico terms steps from 11.3804 in year 3 to 135.2891 in year 4 while gross revenue falls from 219.7286 to 197.5024. What moved?', '["The contractor''s split stepped up a tier, which applies a larger share of profit oil to a residual that was much the same size in both years.", "The royalty rate stepped down as the price deck moved at year 5, so more of the top line survived to reach the residual in year 4.", "The capex finally left the recoverable pool in year 4.", "The cost pool cleared, so recovery stopped taking the whole stream and the residual is what jumped."]'::jsonb, 3, 'The split here is flat at 100 percent and the royalty is flat at 18.75 percent, so neither instrument moved at all.'),
  ('fiscal', 'beginner', 'module', 'm04-the-concession-ledger', 9, 'Year 1 of the default project spends 500.0000 of capex under the Gulf of Mexico terms and pays tax of 0.0000. Why is nothing owed?', '["The capex is deducted from the tax base in the year it is spent.", "The loss in year 1 is carried forward against the tax of the later years, so the year itself settles at nothing and the relief arrives later.", "The base is the contractor''s share of profit oil, and profit oil is 0.0000 that year.", "Corporate income tax at 21 percent starts only once the pool clears."]'::jsonb, 2, 'Cost recovery had already assigned all 220.9910 of revenue after royalty, so the rate had nothing to act on. The model carries no depreciation and no loss carryforward.'),
  ('fiscal', 'beginner', 'module', 'm04-the-concession-ledger', 10, 'Ghana carries the highest corporate rate of the six templates at 35 percent and pays life tax of 230.9340 on the default project, against 422.8854 under Generic at 30 percent. What explains it?', '["Ghana''s tiered split hands the contractor a smaller share of profit oil, so the rate has less to act on.", "Ghana''s royalty of 5 percent leaves more of the top line inside the recoverable pool, and cost recovery is deducted before the tax base is struck.", "Ghana''s cost recovery limit of 90 percent shelters part of the residual from tax in every year until the standing pool has cleared.", "Generic carries a resource rent tax beside its corporate rate, on the same base."]'::jsonb, 0, 'Tax is charged on the contractor''s profit share, so tiers of 70, 50 and 35 percent shrink the base that a 35 percent rate is applied to.'),
  ('fiscal', 'beginner', 'module', 'm04-the-concession-ledger', 11, 'Two published runs share a revenue of 7001.1938 and a profit oil of 3523.7229 and collect life tax of 1638.5664 and 2607.5549. What is different between them?', '["One arms the minimum tax at 10 percent of gross revenue while the other leaves it at 0, which changes the years in which the stack binds.", "One leaves the resource rent tax uplift unstated, which takes the default of 20 percent, and the other sets it to 0.", "One runs the Brazil resource rent rate of 40 percent and the other the Angola rate of 50 percent, on the same contractor profit share.", "One recovers cost at 100 percent and the other at 70 percent, which moves the residual."]'::jsonb, 1, 'A setting nobody typed moved the life tax from 2607.5549 to 1638.5664, which is why an unstated field is read as carefully as a rate.'),
  ('fiscal', 'beginner', 'module', 'm04-the-concession-ledger', 12, 'Year 2 of the Gulf of Mexico ledger on the default project is the largest positive contractor row of the life at 169.7780, and its profit oil is 0.0000. How?', '["It takes a residual of 198.6260 at a flat 100 percent split and pays no tax.", "It collects the profit share the pool held back in year 1.", "It recovers the whole 500.0000 of capex in the one year.", "It recovers 198.6260 of cost oil against opex of 28.8480, pays no tax and carries no capex."]'::jsonb, 3, 'Cost oil is added to the contractor and not subtracted, so the row is 198.6260 less 28.8480 with nothing else in it.'),
  ('fiscal', 'beginner', 'module', 'm04-the-concession-ledger', 13, 'Royalty never appears as a subtraction on the contractor''s line, though it is printed on the row. Why not?', '["It is charged to the government take column instead.", "It is returned to the pool as a recoverable cost in the next year.", "It came off before cost recovery began, so year 1 cost oil of 220.9910 is already net of it.", "It is netted against the tax owed on the contractor''s profit share."]'::jsonb, 2, 'Subtract it a second time and year 1 reads 50.9979 too low, with a life total to match.'),
  ('fiscal', 'beginner', 'module', 'm04-the-concession-ledger', 14, 'Year 1 on the default project shows government take of 50.9979 against a contractor line of -310.0117. What is the state''s figure made of?', '["Royalty plus the state''s share of profit oil, which is small in this year because the residual left after recovery is itself small.", "Royalty alone, collected on gross revenue in a year that destroyed 259.0138 of value.", "Royalty net of the state''s share of the year''s opex and capex.", "Royalty plus tax on the contractor''s share of a residual of 220.9910."]'::jsonb, 1, 'The contractor takes 100 percent of profit oil here and profit oil is 0.0000, so royalty is the whole column. The state carries none of the cost.'),
  ('fiscal', 'beginner', 'module', 'm04-the-concession-ledger', 15, 'Angola charges no royalty at all and collects 1200.2886 on the default project, while the Gulf of Mexico terms charge 18.75 percent and collect 764.5528. Which instruments carry the Angola collection?', '["A 50 percent recovery limit, a tiered split that leaves part of the residual with the state, and resource rent tax at 50 percent.", "A corporate income tax of 25 percent charged on gross revenue rather than on the contractor''s share of the residual.", "A minimum tax that binds in each year where the residual is too small for the ordinary rate to reach.", "A wider revenue base, because a regime that waives its royalty leaves more of the field''s sales to be divided."]'::jsonb, 0, 'Total revenue is 2686.9277 under every template on this project, so the whole of the difference is instrument.'),
  ('fiscal', 'beginner', 'module', 'm05-reading-the-ledger', 1, 'The Gulf of Mexico ledger on the Designer''s default project closes cumulativeNCF at 980.9313. What else in the same ledger must read 980.9313, and what does it mean if it does not?', '["The life total of the contractor net cash flow column, and a disagreement means one of the two was built from a different column.", "The life total of government take, since the running sum is a division of one quantity and the two sides of it must close together.", "The net present value at the project''s 10 percent, because a running sum and a discounted sum differ only in the order they are taken.", "The life total of gross revenue less royalty, because everything else in the cascade is either recovered or carried forward."]'::jsonb, 0, 'The closing cumulative and the contractor total are the same 25 numbers added in the same order, so they are the cheapest check in the ledger.'),
  ('fiscal', 'beginner', 'module', 'm05-reading-the-ledger', 2, 'The deepest point of the cumulative curve under the Gulf of Mexico terms is -310.0117, against a capital spend of 500.0000. Why is the trough shallower than the spend?', '["The capex is spread over the first three years by the recovery machinery, and the trough records only the part charged in year 1.", "The trough is taken after the year''s royalty of 50.9979 has been returned to the contractor through the cost pool.", "The same year recovered 220.9910 of cost oil and paid opex of 31.0027, so the exposure the ledger records is smaller.", "The trough is the discounted value of the year 1 row at the project''s 10 percent, which is smaller than the cash figure."]'::jsonb, 2, 'Under Angola the same project troughs at -323.6112, because a 50 percent recovery limit returned less of the spend in the year it happened.'),
  ('fiscal', 'beginner', 'module', 'm05-reading-the-ledger', 3, 'Under the Gulf of Mexico terms on the default project the cumulative reads -140.2337 in year 2 and 8.9905 in year 3. What is payback, and by what rule?', '["Year 3, interpolated between the two rows to the fraction of the year at which the cumulative crossed zero.", "Year 3, because payback is the first year the cumulative contractor net cash flow stands above zero.", "Year 2, because year 2 is the last year of exposure and the crossing is booked to the year the deficit ended.", "Year 3, because payback is the first year in which the unrecovered cost pool closes at 0.0000."]'::jsonb, 1, 'It is a whole year and not a fraction, and the pool clearing is a separate event that happens to fall in year 3 here as well.'),
  ('fiscal', 'beginner', 'module', 'm05-reading-the-ledger', 4, 'On the default project the PIA and Angola templates report payback in year 4 while payout is year 3, and the other four report 3 for both. What does the one year gap say?', '["The R factor and the cumulative are computed on different production profiles, so the two clocks are never strictly comparable.", "The pool cleared a year later under those two templates, and payback cannot be reported before the pool closes.", "Payout is discounted at the project''s 10 percent and payback is not, so payout always arrives in an earlier year.", "The project earned its cost back before the contractor got its cash back, because the state takes its share in between."]'::jsonb, 3, 'Payout is the first year the R factor is above 1.0, cumulative revenue over cumulative cost, and it knows nothing about who kept the money.'),
  ('fiscal', 'beginner', 'module', 'm05-reading-the-ledger', 5, 'A published case caps cost recovery at 5 percent, closes the life with 2543.7575 still unrecovered, and is named for a pool that never recovers. What does it report for payback?', '["No payback at all, with an IRR of 0, since a pool that never clears is a project that never returns its capital.", "Payback in year 3, with an IRR of 54.6792 percent and a life contractor total of 1530.0622.", "Payback in year 3 on a life total of 1530.0622, but with the IRR suppressed to 0 because the pool never closed.", "No payback, because the engine reports payback only once the closing unrecovered pool has reached 0.0000."]'::jsonb, 1, 'The revenue the limit could not recover became profit oil, and this regime splits profit oil 100 percent to the contractor, so the capital came home through the profit share.'),
  ('fiscal', 'beginner', 'module', 'm05-reading-the-ledger', 6, 'Four of the six templates report payback in year 3 on the default project. Why is that a poor place to rank them?', '["Payback is measured on the discounted cumulative, and the discounting compresses the differences between the templates into one year.", "Payback is measured from the R factor, which is a ratio of cumulatives and moves too little between templates to separate them.", "Payback is a whole year, so a tie in the column is not a tie in the money: the same year 3 covers 986.7327 under Generic and 912.1029 under Brazil.", "Payback is reported to the nearest year and the engine rounds up, so four templates that really differ are printed as the same year."]'::jsonb, 2, 'It is an integer clock on an undiscounted running sum, and it has no view of anything that happens after the crossing.'),
  ('fiscal', 'beginner', 'module', 'm05-reading-the-ledger', 7, 'The published case at capex 20000 returns payback null and payout null. What is the correct way to read that pair?', '["As a reading in its own right: the cumulative was never above zero and the R factor never above 1.0 in any of the 25 rows.", "As a gap in the table, since the engine leaves the field empty when a project is stopped before the horizon is reached.", "As a sign the run was terminated early, so the rows after the shut in were never computed and never taxed.", "As an error state, since a project that cannot pay back is outside the range the sandbox is able to report on."]'::jsonb, 0, 'Every one of the 25 rows was still computed and still counted: government take is royalty of 875.1492 on revenue of 7001.1938.'),
  ('fiscal', 'beginner', 'module', 'm05-reading-the-ledger', 8, 'Run all six templates on the default project. Opex and capex are the project''s own and print identically on every line whatever the terms are. Which two of the remaining seven totals are also identical on all six lines, and why?', '["Total revenue at 2686.9277 and total profit oil at 1241.6852, because the regime divides the residual between the two sides without changing its size.", "Total royalty at 503.7989 and total capex at 500.0000, because the royalty base and the capital spend are both fixed before any regime is applied.", "Total cost recovered at 941.4436 and total tax at 260.7539, because the recovery machinery runs the same way under every one of the six templates.", "Total revenue at 2686.9277 and total cost recovered at 941.4436, because the regime never touches price or production and every pool clears inside the life here."]'::jsonb, 3, 'Cost recovered matches the life costs only when the pool empties. On the test project none of them empties, from 72.7082 under Brazil to 251.6537 under Angola.'),
  ('fiscal', 'beginner', 'module', 'm05-reading-the-ledger', 9, 'Brazil pays the most tax of the six templates on the default project at 564.6884 and leaves the contractor 912.1029, the second highest figure in the table. What does that show?', '["That the tax column is charged on gross revenue under Brazil and on the profit share under the other five, so the two are not comparable.", "Tax and take rank differently, because the state also collects through royalty and through its share of profit oil.", "That the resource rent tax of 40 percent is refunded to the contractor through the cost pool, which is why the cash survives the tax.", "That a high tax bill signals a high residual, so the contractor''s cash and the tax column will normally move together across templates."]'::jsonb, 1, 'PIA pays the least tax of the six, 174.0882, and leaves the contractor the least cash, 406.2057.'),
  ('fiscal', 'beginner', 'module', 'm05-reading-the-ledger', 10, 'Contractor total 980.9313 and government total 764.5528 do not add to revenue of 2686.9277 on the default project. What is the difference?', '["Cost recovered of 941.4436, which is assigned to the contractor''s cash separately and so is counted outside the two takes.", "The royalty of 503.7989, which is settled off the top line before the two takes are struck and is reported on its own row.", "Opex of 441.4436 and capex of 500.0000, which are the contractor''s alone and belong to neither take.", "The closing unrecovered pool, which holds the revenue neither side was able to claim within the horizon of 25 years."]'::jsonb, 2, 'The two takes add to revenue less opex less capex on every row, and 441.4436 plus 500.0000 is the whole of the gap in the totals.'),
  ('fiscal', 'beginner', 'module', 'm05-reading-the-ledger', 11, 'On the teaching field ODIDI every template closes its cumulative in the black and every template returns a negative value at the project''s 12 percent. What does that pair of readings mean?', '["The field returns the contractor''s nominal money and still is not worth building at the rate the project is discounted at.", "The cumulative was computed on a different set of rows from the value, so one of the two readings has to be discarded.", "The field pays back inside the horizon but the closing unrecovered pool is larger than the cash returned in every case.", "The value is negative because the horizon of 25 years ends before the cumulative has finished climbing."]'::jsonb, 0, 'Brazil ends the life with 192.9896 of contractor cash and a value of -5.8662, and Angola with 109.1947 and -58.1813.'),
  ('fiscal', 'beginner', 'module', 'm05-reading-the-ledger', 12, 'A cumulative curve does not only rise. What turns it back down late in the life of a declining field?', '["The unrecovered cost pool refilling, which is subtracted from the cumulative in the year the balance starts to grow again.", "The discount exponent growing with the year number, until each new row shrinks to nothing.", "The abandonment provision, which the engine charges against the last rows of the life once production has fallen far enough.", "A year whose revenue after royalty no longer covers the year''s opex, which makes the contractor''s line negative."]'::jsonb, 3, 'ODIDI''s year 25 sells 6.9081 of gross revenue against opex of 12.3405 under the Gulf of Mexico terms, so the row is negative and the running sum falls.'),
  ('fiscal', 'beginner', 'module', 'm05-reading-the-ledger', 13, 'Swept from 40 to 120 USD per bbl on ODIDI, the government share under the Gulf of Mexico terms falls from 78.5512 percent to 40.8517 while under PIA it stays within 75.1077 to 79.4678. What does a single ledger tell you about that?', '["It tells you the ranking at the run''s own price, and that ranking holds across the sweep.", "Nothing at all, because one run is one price deck and the shape of a regime across prices is not in it.", "It tells you the direction of the movement, since a regime with a higher take at the base price always gives up more of it as prices rise.", "It tells you which template is progressive, from the government share at the base price."]'::jsonb, 1, 'Two regimes that look similar on one run behave nothing alike on the next, and the single ledger shows neither shape.'),
  ('fiscal', 'beginner', 'module', 'm05-reading-the-ledger', 14, 'Across the swept capex range on ODIDI, Ghana gives up 150.9021 of contractor value and Angola gives up 215.1075. What does that difference measure?', '["Which regime has the higher capex, since the sweep moves each template''s own spend by its own multiplier before the ledgers are run.", "Which regime discounts the overrun hardest, since the value given up is a present value.", "Which regime makes the contractor carry more of a cost overrun, which is decided by the instruments that recover cost.", "Which regime has the larger tax base, since an overrun is deducted from tax in the year it is spent."]'::jsonb, 2, 'One ledger at one capex never asks the question, and the cost columns themselves are identical under all six templates.'),
  ('fiscal', 'beginner', 'module', 'm05-reading-the-ledger', 15, 'The same Gulf of Mexico terms return 980.9313 to the contractor on the default project and 2221.9251 on the Suite test project. What has been shown?', '["That the test project is a bigger field, turning over 7001.1938 of revenue against 2686.9277, and nothing at all about the regime.", "That the terms are more generous on the higher price deck of the test project, which prices its oil at 80 USD per bbl in every one of the 25 years.", "That a single stream project recovers cost faster, because gas and NGL volumes never enter the boe the opex is charged on.", "That the regime is better suited to a project whose capex is larger, which the test project''s 1000 of spend confirms."]'::jsonb, 0, 'Totals only compare across regimes on one project, because that is the design that holds revenue constant at 2686.9277 on every line.'),
  ('fiscal', 'beginner', 'module', 'm06-the-associate-reading', 1, 'The teaching field ODIDI sells 139.6563 in year 1 under the Gulf of Mexico terms. What are the royalty and the revenue after royalty for that year?', '["Royalty 10.4742, which is the 7.5 percent tier a deck price of 45 USD per bbl selects, on gross revenue of 139.6563.", "Royalty 26.1856 and revenue after royalty 113.4707, charged before any cost is considered.", "Royalty 26.1856 and revenue after royalty 113.4707, struck after the year''s opex of 25.0037 has been taken off the top line.", "Royalty 0.0000, since a year spending 420.0000 of capex has no base to charge."]'::jsonb, 1, 'A flat 18.75 percent is charged on gross revenue in every year, including the year that carries the whole 420.0000 of capex.'),
  ('fiscal', 'beginner', 'module', 'm06-the-associate-reading', 2, 'ODIDI''s gross revenue falls to 76.1939 in year 5 and rises to 93.9859 in year 6, while every stream declines throughout. What did that?', '["The oil decline of 14 percent a year starts only at year 6, so the early years fall faster.", "The gas and NGL streams decline more slowly, and by year 6 they carry enough of the mix to lift the total.", "The deck steps from 45 to 65 USD per bbl at year 6, and the step is large enough to outrun a 14 percent oil decline.", "The deck interpolates between its year 1 and year 6 points, so the applied price climbs through the early years and arrives at year 6."]'::jsonb, 2, 'The deck holds 45 through year 5 and never interpolates, so the whole move arrives in one row.'),
  ('fiscal', 'beginner', 'module', 'm06-the-associate-reading', 3, 'Under the Gulf of Mexico terms, at a cost recovery limit of 100 percent, ODIDI still closes its life with 24.2824 unrecovered. How does a full limit leave a balance behind?', '["The limit is a percent of gross revenue, so the 1.2953 of royalty in year 25 is outside the ceiling and is never recoverable.", "The capex of 420.0000 is charged whole in year 1 and only one year''s worth of it may be recovered in any later year.", "The pool is closed at the end of year 25 and whatever it holds at that point is written off rather than recovered.", "Late revenue after royalty of 5.6128 in year 25 cannot absorb the year''s opex of 12.3405, so the pool starts filling again."]'::jsonb, 3, 'A full limit is a ceiling on revenue after royalty, and on a field declining 14 percent a year the late rows have very little of it.'),
  ('fiscal', 'beginner', 'module', 'm06-the-associate-reading', 4, 'Every one of the six templates leaves ODIDI with a closing unrecovered pool, from 19.3270 to 192.1146. What separates the two ends of that range?', '["The cost recovery limit, which is 100 percent under Brazil and 50 percent under Angola.", "The royalty, which is 10 percent under Brazil and 0 percent under Angola, so Brazil has less revenue after royalty to recover against.", "The profit split, which is flat under Brazil and tiered under Angola, so a smaller share of the residual is available to clear the pool.", "The tax stack, since Angola''s resource rent tax at 50 percent takes cash the contractor would otherwise recover cost with."]'::jsonb, 0, 'A tighter limit leaves more of the year 1 capex waiting, and on a field that declines 14 percent a year the later revenue never catches up.'),
  ('fiscal', 'beginner', 'module', 'm06-the-associate-reading', 5, 'ODIDI under Brazil returns the contractor 192.9896 over 25 years, the most of the six templates, and a value of -5.8662 at the project''s 12 percent. How can both be true?', '["The value is computed on the government''s cash flows rather than the contractor''s, which is why it carries the opposite sign.", "The internal rate is 11.4055 percent, which is under the 12 percent the project is discounted at, so positive nominal cash is still worth less than nothing today.", "The 192.9896 is a total of undiscounted rows and the value excludes the capex, so the two are not readings of the same ledger.", "The closing unrecovered pool of 19.3270 is subtracted in the value and not in the total, and that is the whole of the difference."]'::jsonb, 1, 'Same rows, two verdicts. Every one of the six templates closes ODIDI''s cumulative in the black and returns a negative value at 12 percent.'),
  ('fiscal', 'beginner', 'module', 'm06-the-associate-reading', 6, 'The capstone method says to build year 1 by hand before reading any column. Why year 1?', '["It is the only year in which the cost recovery limit binds, so the ceiling can be checked against the ledger before anything else.", "It is the year the R factor selects the first tier of a split, and every later year inherits the tier that year established.", "It holds the whole of the capex, so the mistakes are loudest there.", "It carries no tax under any of the six templates, which makes it the one row that can be built without the tax rates."]'::jsonb, 2, 'On the default project year 1 is grossRevenue 271.9889, royalty 50.9979, cost recovered 220.9910, a pool of 310.0117 and a contractor line of -310.0117.'),
  ('fiscal', 'beginner', 'module', 'm06-the-associate-reading', 7, 'Your hand built year 1 of the Gulf of Mexico ledger on the default project comes out at 50.9979 below the engine''s -310.0117. What is the error?', '["Cost recovery was taken on gross revenue of 271.9889 rather than on revenue after royalty of 220.9910.", "The opex of 31.0027 was charged both as a cash cost and again inside the recoverable pool for the year.", "The tax was computed on the whole residual instead of on the contractor''s share of it under the flat 100 percent split.", "Royalty was subtracted a second time, after it had already been taken off the top line before cost recovery."]'::jsonb, 3, 'Cost oil of 220.9910 is already net of the royalty, and the gap between the two figures names the error exactly.'),
  ('fiscal', 'beginner', 'module', 'm06-the-associate-reading', 8, 'A hand built year 1 shows an unrecovered cost pool of 500.0000 on the default project where the engine prints 310.0117. What was missed?', '["The year''s own recovery, 220.9910 of cost oil, which is credited before the pool is carried forward.", "The opex of 31.0027, which belongs in the pool alongside the capex and was left out of the recoverable balance.", "The royalty of 50.9979, which is added to the pool in the year it is paid and recovered in the years after it.", "The tax of 0.0000, which is credited to the pool where the residual is nothing."]'::jsonb, 0, 'The pool is the balance brought forward plus the year''s capex and opex, less what was recovered, so 310.0117 is what remains.'),
  ('fiscal', 'beginner', 'module', 'm06-the-associate-reading', 9, 'The method''s third step proves a row after the pool has cleared. On the default project year 4 recovers 25.1816, exactly its opex. What does a larger figure in that row mean?', '["The limit was read as a percent of gross revenue, which raises the ceiling and lets the year recover more than it spent.", "The pool was not cleared in year 3, so a carried balance is still being recovered.", "The capex was spread over the early years instead of being charged whole to year 1, leaving a part of it to recover in year 4.", "The profit split was applied before cost recovery rather than after it, which moves part of the residual into the recovered column."]'::jsonb, 1, 'Year 3 recovers 167.1490 and closes the pool at 0.0000, so from year 4 the recovered figure and the opex figure are one number.'),
  ('fiscal', 'beginner', 'module', 'm06-the-associate-reading', 10, 'Three of these four statements name a check that a single row of the ledger can settle on its own. Which one names a check that cannot be settled that way?', '["That the two takes add to gross revenue less opex less capex, which needs the totals row.", "That tax is 0.0000 in a year whose profit oil is 0.0000, which cannot be settled until the tax column has been totalled.", "That the closing cumulative equals the life total of the contractor column, since it needs all 25 rows.", "That the contractor line rebuilds from cost oil plus the profit share, less tax, less opex and less capex, which needs the totals row to settle."]'::jsonb, 2, 'A single row rebuilds the contractor line, settles the identity at -259.0138 in year 1 and settles the zero tax on a zero residual. The cumulative check closes at 980.9313 on both sides and needs all 25 rows to do it.'),
  ('fiscal', 'beginner', 'module', 'm06-the-associate-reading', 11, 'The capstone method proves two rows and reads the other twenty three. What does it not catch?', '["A royalty charged on the wrong base, because the error is invisible until the pool has cleared several years later.", "A tax charged on a residual of 0.0000, which only becomes visible once the totals row has been assembled.", "A capex that has been spread across the early years, since the year 1 row would still balance under either treatment.", "A tier crossing, a deck step or a pool that refills late in life, none of which show in the two rows it proves."]'::jsonb, 3, 'Nothing in the method discounts anything either, and ODIDI''s value of -37.3123 under the Gulf of Mexico terms is invisible to it.'),
  ('fiscal', 'beginner', 'module', 'm06-the-associate-reading', 12, 'ODIDI pays back in year 6 under Brazil, year 7 under the Gulf of Mexico terms and year 8 under Angola. What does that spread require of anyone quoting a reading from this field?', '["Name the regime beside the reading, because payback in year 6 and payback in year 8 are both true of the same field.", "Quote the fastest of the six, since the earliest crossing is the one that bounds the field''s exposure.", "Quote the median of the six templates, which is the reading least sensitive to the choice of terms.", "Quote the payout year of 6 instead, which is the same under all six and so belongs to the field."]'::jsonb, 0, 'The same field returns 148.3166 of contractor cash under the Gulf of Mexico terms and 192.9896 under Brazil.'),
  ('fiscal', 'beginner', 'module', 'm06-the-associate-reading', 13, 'ODIDI hands the state between 232.9950 and 316.7898 depending on which of the six templates prices it. What can the Associate reading not say about that range?', '["Which template collects the most, since the six collections are only comparable when the closing pools are equal.", "Which template leaves the contractor the least cash, which needs a discount convention the tier does not carry.", "Which of the splits is fair, which survives a price collapse, and which numbers on a comparison screen are measurements at all.", "How much of each collection is royalty, since the ledger prints government take as a single undivided column."]'::jsonb, 2, 'The contractor keeps between 109.1947 and 192.9896 across the same six templates, and the tier can state the range without judging it.'),
  ('fiscal', 'beginner', 'module', 'm06-the-associate-reading', 14, 'Every regime in the Associate tier was read at one setting. Which instruments actually move on their own in the templates this tier held still?', '["The cost recovery limit, which tightens as the standing pool grows, and the minimum tax, which arms itself once the residual falls.", "A royalty keyed on price and a profit split keyed on the R factor, which under PIA steps the contractor''s share from 60 to 40 to 30 percent.", "The corporate rate, which steps with the R factor tier, and the royalty, which steps with cumulative production.", "The discount rate, which follows the price deck, and the profit split, which follows the closing unrecovered pool."]'::jsonb, 1, 'The R factor is a ratio of cumulatives, so it can fall back below a threshold it passed and step the contractor''s share up again.'),
  ('fiscal', 'beginner', 'module', 'm06-the-associate-reading', 15, 'A published run leaves the resource rent tax uplift unstated and collects life tax of 1638.5664, where the run that sets it to 0 collects 2607.5549. What is the habit that catches this?', '["Compare the two tax columns row by row, since a difference of this size is always visible in the first year of a life of 25 rows.", "Rank the templates by their headline corporate rate first, which is the field the two runs actually differ in.", "Total the government take rather than the tax, because the take is the only column a default setting cannot move.", "Read what the regime does not state as carefully as what it does, because an unstated field takes a default of 20 percent."]'::jsonb, 3, 'Both runs share a revenue of 7001.1938 and a profit oil of 3523.7229, so a number nobody typed moved the tax by that much.'),
  ('fiscal', 'beginner', 'final', null, 1, 'Which of these can a fiscal regime in this sandbox actually express?', '["A ceiling on cost recovery, written as a percent of revenue after royalty.", "A signature bonus payable to the state in the year the licence is awarded.", "A state participation share carried through the development and paid out of production.", "A flare penalty charged on the gas stream in every year it is not utilised."]'::jsonb, 0, 'A regime is royalty, cost recovery limit, profit split and a tax stack holding CIT, RRT, a minimum tax and an optional uplift. Nothing else exists.'),
  ('fiscal', 'beginner', 'final', null, 2, 'PIA and Generic both carry corporate income tax at 30 percent, resource rent tax at 0 and a minimum tax of 0, yet the default project returns 406.2057 to the contractor under PIA and 986.7327 under Generic. What opened the gap?', '["The PIA sliding royalty, which reaches 10 percent on this deck against the Generic flat rate of 12.5 percent.", "The tax base, which is gross revenue under PIA and the contractor''s profit share under Generic.", "A cost recovery limit of 80 percent instead of 100, and an R factor split handing over 60, then 40, then 30 percent of profit oil instead of all of it.", "The production profile, which the PIA template shortens to the years in which its tranches apply."]'::jsonb, 2, 'PIA pays the smaller tax bill of the two, 174.0882 against 422.8854, and still leaves the contractor less than half the cash. A tax rate quoted alone predicts nothing.'),
  ('fiscal', 'beginner', 'final', null, 3, 'How many rows does calculateCashFlowForRegime return, and what changes that count?', '["25 rows by default, extended automatically while the field is still producing above its economic limit.", "As many rows as the price deck carries points for, so a three point deck returns a shorter ledger.", "25 rows for a project that pays back, and rows only up to the year payback is reported in when it does not.", "25 rows for every regime and every project, and no input changes it."]'::jsonb, 3, 'PROJECT_LIFE is fixed at 25, so year 25 of the default project still produces 0.291148 million bbl of oil and still costs 11.5851 of opex.'),
  ('fiscal', 'beginner', 'final', null, 4, 'A template field reads 18.75 and a derived column reads 0.187500. What is the relation?', '["The field is the rate before the boe conversion and the column is the same rate after it.", "They are one instrument in two conventions, a percent and a ratio, and 0.187500 percent would never produce a royalty of 50.9979 on 271.9889.", "The field is the statutory rate and the column is the rate actually collected once the pool has cleared.", "The field is the rate on gross revenue and the column is the same rate restated on revenue after royalty."]'::jsonb, 1, 'Rates are percent and a value of 10 means ten percent. The implied rate column is royalty over gross revenue, printed to six decimals.'),
  ('fiscal', 'beginner', 'final', null, 5, 'The published case at capex 20000 produces for 25 years, loses 15724.0151 and hands the treasury 875.1492. Which two omissions let that happen?', '["No depreciation and no loss carryforward, so the losses of the early years never shelter the later ones from tax.", "No ring fence and no valuation date, so the losses of one field are never set against the profits of another.", "No economic limit and no abandonment cost, so nothing shuts the field in and nothing is paid at the end.", "No price escalation and no inflation, so a deck that ends in year 10 prices the last fifteen years too low."]'::jsonb, 2, 'Total tax is 0.0000 and total profit oil is 0.0000, so the government take is pure royalty on revenue of 7001.1938.'),
  ('fiscal', 'beginner', 'final', null, 6, 'The engine returns a total government take of 1339.2784 under the PIA template on the default project. What is that number?', '["A shape, useful for asking which instrument moved which result, and unfit for filing anything.", "An assessment of the Nigerian take on a deepwater project, computed under the Petroleum Industry Act.", "A screening estimate that the Petroleum Economics Studio engine would reproduce to within a rounding.", "A statutory minimum, since the templates are calibrated to the floor each jurisdiction would accept."]'::jsonb, 0, 'The engine''s own header says the single source of truth for Nigerian fiscal math is the Petroleum Economics Studio engine, and that this model compares the shape of regimes.'),
  ('fiscal', 'beginner', 'final', null, 7, 'ODIDI is declared at 8000 bbl/d of oil declining 14 percent a year, and its first year lifts 2.920000 million bbl. What has become of that year''s decline?', '["It is applied at the midpoint of year 1, which is why the figure is close to the undeclined volume but not equal to it.", "Nowhere. The decline is applied after the year is booked, so year 1 is the rate times 365 days undeclined.", "It is deferred to year 2, which carries two years of decline at once to keep the cumulative correct.", "It is applied to the price rather than the volume in the first year, so the revenue carries it instead."]'::jsonb, 1, 'The Designer''s own field declares 10000 bbl/d and lifts 3.650000 million bbl in its first year on the same rule.'),
  ('fiscal', 'beginner', 'final', null, 8, 'ODIDI carries deck points of 45 in year 1, 65 in year 6 and 85 in year 12. What oil price is applied in year 5, and in year 25?', '["A price between 45.000000 and 65.000000 in year 5, and 85.000000 in year 25, because the deck interpolates and then holds.", "45.000000 in year 5 and a figure above 85.000000 in year 25, since the engine escalates past the deck''s last point.", "65.000000 in year 5 and 85.000000 in year 25, because a deck point applies from the year before it is dated.", "45.000000 in year 5 and 85.000000 in year 25, because the deck holds each point until the next and never escalates past the last."]'::jsonb, 3, 'The deck holds 45 through year 5, steps to 65 at year 6 and to 85 at year 12, and no column in the output reports the price.'),
  ('fiscal', 'beginner', 'final', null, 9, 'Year 25 opex is 11.5851 on the default project and 12.3405 on ODIDI, though ODIDI charges 4 USD per boe against the default project''s 5. Why is the smaller field dearer at the end?', '["ODIDI''s oil declines at 14 percent a year, and a faster decline raises the cost of every barrel that is left.", "ODIDI''s deck prices oil at 85 USD per bbl by year 25, and the variable half of opex is charged on the value produced.", "By year 25 almost the whole bill is the fixed half, and ODIDI''s fixed half is 12 million USD a year against 10.", "ODIDI carries a larger closing unrecovered pool, and the pool is added to the year''s opex until it clears."]'::jsonb, 2, 'Opex is fixed plus variable times the boe, so the curve heads for the fixed number and would only arrive there at zero production.'),
  ('fiscal', 'beginner', 'final', null, 10, 'The capex multiplier on the flat regime moves the test project NPV from 1262.3470 to 1062.6176 at 1.3 and to 1460.6941 at 0.7. What does it not do?', '["Move the IRR, which stays at 124.5777 percent because the multiplier scales the cash flows in proportion.", "Phase the spend, because every dollar of capex is charged in year 1 whatever the multiplier is.", "Change the recoverable pool, since the pool is seeded from the revenue side and not from the capex.", "Alter the royalty, which is the one column the multiplier is allowed to reach through gross revenue."]'::jsonb, 1, 'Faking a schedule by lowering the multiplier changes the total rather than the timing, and answers a different question.'),
  ('fiscal', 'beginner', 'final', null, 11, 'Year 1 of the default project lifts 3.650000 million bbl of oil and 0.018250 million Mscf of gas. What is wrong with calling the gas negligible on those two figures?', '["They are not the same unit. One is million bbl and the other million Mscf, and gas converts at 6000 scf per barrel for opex.", "The gas declines at 8 percent against the oil''s 10, so its share of the barrel mix grows through the life.", "The gas is priced at 3.5 USD in year 1 and 4.5 from year 10, so its revenue grows while its volume falls.", "The gas column is quoted before shrinkage while the oil column is quoted after it, so the two are not comparable."]'::jsonb, 0, 'The conversion exists for one purpose, the variable half of opex, which is charged in USD per boe.'),
  ('fiscal', 'beginner', 'final', null, 12, 'On the default project gas falls from 0.018250 to 0.002467 million Mscf between year 1 and year 25 while NGL falls from 0.547500 to 0.025466 million bbl. Why does the gas keep the larger fraction of itself?', '["The gas price steps from 3.5 to 4.5 USD across the life, which holds the gas volume up in the later years.", "Gas is converted at 6000 scf per barrel, and the conversion compresses its decline once the column is scaled.", "The gas stream is held at the deck''s last point from year 10, so its volume stops falling while the liquids carry on.", "Each stream carries its own decline, and the gas declines at 8 percent a year against the NGL at 12."]'::jsonb, 3, 'Three independent exponentials, so their proportions move: ODIDI shows the same thing harder at 9 percent on gas against 15 on NGL.'),
  ('fiscal', 'beginner', 'final', null, 13, 'Gross revenue in year 1 of the default project is 271.9889. What has been taken out of it?', '["Transport and processing, which is why it is described as a revenue rather than a wellhead value.", "The royalty, which is charged at the point of sale and so never appears in the top line of the ledger.", "Nothing at all. It is three volumes at their deck prices, divided by one million.", "A quality differential on the oil stream, which the deck''s single price per stream per year already carries."]'::jsonb, 2, 'The royalty base is exactly this number, and 18.75 percent of it is the 50.9979 the Gulf of Mexico terms collect.'),
  ('fiscal', 'beginner', 'final', null, 14, 'Under the Gulf of Mexico terms the implied royalty rate reads 0.187500 in year 1 and in year 25, on both the default project and ODIDI. What does the derived column prove?', '["That the deck never crossed a tier threshold in either field, which a sliding instrument would have done.", "That the rate is flat, charged on gross revenue whatever the year did.", "That the royalty is settled after cost recovery, since a rate on a moving base could not stay constant.", "That the two fields share a price deck, because the implied rate is a ratio of revenue to volume."]'::jsonb, 1, 'Year 1 of the default project pays 50.9979 on 271.9889 and year 25 pays 4.5603 on 24.3216.'),
  ('fiscal', 'beginner', 'final', null, 15, 'Revenue after royalty is not a column the engine prints, yet it decides the size of cost recovery. Why does it matter which base is used?', '["The cost recovery limit is a percent of it, so on year 1 of the default project the ceiling is 220.9910 and not 271.9889.", "The royalty is charged on it, so using gross revenue instead overstates the state''s collection in every year.", "The profit split acts on it directly, so a flat 100 percent split returns it whole to the contractor.", "The R factor is computed from it, so the tier a split selects moves with the base that was chosen."]'::jsonb, 0, 'The difference is exactly the royalty, 50.9979 of extra recovery in the first year alone, and it flows into the pool and into every R factor keyed on it.'),
  ('fiscal', 'beginner', 'final', null, 16, 'Nigeria PIA and Brazil collect exactly the same total royalty on both published projects, 268.6928 and 700.1194. One is a slider and one is flat 10 percent. How?', '["The slider averages its two tiers of 7.5 and 10 percent across the life, which lands on the flat rate.", "A sliding royalty defaults to the flat rate of the template it is compared against when no tier is crossed.", "The two templates share a cost recovery limit, and royalty is charged after the limit has been applied.", "Every applied price in both fields is above the slider''s 50 USD per bbl threshold, so it sits in its 10 percent tier throughout."]'::jsonb, 3, 'The default project prices oil at 70, 75 and 80 and the test project at 80, so a sliding instrument that never slides is a flat one.'),
  ('fiscal', 'beginner', 'final', null, 17, 'Angola collects total royalty of 0.0000 on the default project and still leaves the contractor 545.1955, against 980.9313 under the Gulf of Mexico terms at 18.75 percent. Which fields make Angola the harsher regime?', '["Its corporate income tax of 25 percent, which is charged on gross revenue rather than on the profit share.", "Its minimum tax, which binds in the years when the contractor''s residual is too small to reach.", "Its cost recovery limit of 50 percent, its tiered split, and resource rent tax at 50 percent.", "Its royalty of 0 percent, which leaves a larger base for the tax stack to be charged on."]'::jsonb, 2, 'A regime cannot be ranked by the instrument its press release quotes. Total revenue is 2686.9277 under both.'),
  ('fiscal', 'beginner', 'final', null, 18, 'The six templates fall into two families. What defines the family that Brazil, the Gulf of Mexico and Generic belong to?', '["A flat royalty rate, which the other three replace with a slider keyed on the oil price.", "A flat split handing the contractor 100 percent of profit oil, with cost recovery at a 100 percent limit.", "A tax stack with no resource rent tax, which is what leaves the contractor the whole of the residual.", "A cost recovery limit above 80 percent, which stops the pool from ever carrying a balance forward."]'::jsonb, 1, 'That is what a concession looks like inside a model built around a production sharing ledger, and the other three cap recovery at 80, 90 and 50 percent.'),
  ('fiscal', 'beginner', 'final', null, 19, 'Which statement about the contractor and government columns holds in every year, for every one of the six templates, at every cost recovery limit they use?', '["Added together they equal gross revenue, since every dollar sold is assigned to one side or the other.", "Added together they equal gross revenue less opex less capex only while the cost recovery limit is not binding.", "Added together they equal gross revenue less opex less capex, less whatever moved into the unrecovered pool that year.", "Added together they equal gross revenue less opex less capex."]'::jsonb, 3, 'Swept across all six templates on all three projects, 450 rows, the largest disagreement between the two sums is 1.7053e-13.'),
  ('fiscal', 'beginner', 'final', null, 20, 'That identity holds across every published case. What is the one condition stated on it?', '["It holds only while the pool clears inside the life, since a closing balance leaves revenue assigned to nobody.", "It holds only for a flat profit split, because a tiered split moves part of the residual between the two takes.", "It holds while the cost recovery limit is 100 percent or less, which covers every template and every published case.", "It holds only in years with no capex, because capex enters the ledger twice, as cash and through the pool."]'::jsonb, 2, 'Profit oil is floored at zero, so a limit above 100 percent could in principle recover more than revenue after royalty. Nothing in the template set does this.'),
  ('fiscal', 'beginner', 'final', null, 21, 'A reader building the contractor''s line treats costRecovered as a cost rather than as revenue, and takes it out of the line. What is the error?', '["Cost oil is revenue assigned to the contractor and is added, so year 1 comes out 220.9910 too low.", "Cost oil is a cost but belongs in the year the spend happened, so it should be subtracted in year 1 alone.", "Cost oil is already net of the year''s opex, so subtracting it charges the opex of 31.0027 a second time.", "Cost oil is a government payment, so subtracting it moves 220.9910 onto the wrong side of the row."]'::jsonb, 0, 'Contractor net cash flow is cost oil plus the profit share, less tax, less opex, less capex, and year 1 reads -310.0117.'),
  ('fiscal', 'beginner', 'final', null, 22, 'A reader builds the tax base as revenue less opex less capex, then checks year 4 of the Gulf of Mexico ledger, which prints tax of 28.4107 on profit oil of 135.2891. What goes wrong?', '["The capex is deducted in a year that carries none, so the base is unchanged and the answer happens to agree.", "The year''s opex of 25.1816 is deducted twice, once through cost recovery and again in the invented base.", "The royalty of 37.0317 is left in the base, so the tax comes out above 28.4107 rather than below it.", "The base is right but the rate is wrong, since the corporate rate applies to the state''s share and not the contractor''s."]'::jsonb, 1, 'The base in this model is the contractor''s share of profit oil. That is also why year 1 pays 0.0000 while spending 500.0000 of capex.'),
  ('fiscal', 'beginner', 'final', null, 23, 'Year 4 of the Gulf of Mexico ledger on the default project reports government take of 65.4424. What is in it?', '["Royalty of 37.0317 and the state''s half of a residual of 135.2891, with the tax settled inside that share.", "Tax of 28.4107 and the state''s share of cost oil, since recovery is charged against the state''s own entitlement.", "Royalty of 37.0317 alone, with the tax of 28.4107 reported separately and not counted into the take.", "Royalty of 37.0317 and tax of 28.4107, with no profit share because the contractor takes all of the residual."]'::jsonb, 3, 'The state''s line is royalty plus its share of profit oil plus tax, and here the middle term is nothing.'),
  ('fiscal', 'beginner', 'final', null, 24, 'A published case arms a minimum tax at 10 percent of gross revenue with corporate income tax at 0. What does it collect over the life?', '["0.0000 of tax, because a corporate rate of 0 leaves no base for a minimum to be measured against.", "1006.6134 of tax, the same as the flat regime, because the minimum can never exceed the ordinary charge.", "700.1194 of tax on total revenue of 7001.1938, because the minimum binds in every year.", "700.1194 of tax, charged only in the years whose profit oil was too small to reach the ordinary rate."]'::jsonb, 2, 'A minimum tax is charged on gross revenue rather than on the profit share, which is why it binds in a year with no residual at all.'),
  ('fiscal', 'beginner', 'final', null, 25, 'Angola closes year 1 of the default project at -323.6112 against -310.0117 under the Gulf of Mexico terms, on the same gross revenue of 271.9889, opex of 31.0027 and capex of 500.0000. What did it?', '["A royalty of 0 percent, which leaves more revenue in the pool and therefore less cost oil in the year.", "A 50 percent recovery limit and a split that keeps part of the residual for the state.", "A resource rent tax of 50 percent charged in year 1 on the contractor''s share of the residual.", "A larger capex, since the Angola template applies its own multiplier to the drilling and facilities buckets."]'::jsonb, 1, 'The state''s slice rises from 50.9979 to 64.5974 in the same year, and the two takes still add to -259.0138 under both.'),
  ('fiscal', 'beginner', 'final', null, 26, 'Profit oil under the Gulf of Mexico terms totals 1241.6852 over the life of the default project, the smallest of the six templates, while Angola''s totals 1745.4841, the largest. Which regime returns the contractor more?', '["The Gulf of Mexico terms, at 980.9313 against 545.1955, because the residual is not the contractor''s cash.", "Angola, since a larger residual is the pool that a tiered split draws from, and its first tier hands the contractor 70 percent.", "Angola, because its royalty of 0 percent leaves the whole of the top line inside the ledger.", "Neither, because the two are equal once the closing unrecovered pool has been added back to the contractor."]'::jsonb, 0, 'Royalty and the recovery limit sit upstream of the residual, so a bigger residual can mean a harsher regime rather than a kinder one.'),
  ('fiscal', 'beginner', 'final', null, 27, 'You are handed a ledger whose closing cumulativeNCF and whose life total of contractor net cash flow disagree. What have you learned?', '["That the ledger carries a closing unrecovered pool, which the total counts and the running sum does not.", "That the cumulative is discounted at the project rate while the total is not, so the two only agree at a rate of 0.", "That one of the two was built from a different column, because they are the same 25 numbers added the same way.", "That a year in the middle of the life turned negative, which breaks the running sum but not the total."]'::jsonb, 2, 'On the Gulf of Mexico ledger for the default project both read 980.9313, and it is the cheapest check there is.'),
  ('fiscal', 'beginner', 'final', null, 28, 'A case named for a cost pool that never recovers closes the life with 2543.7575 unrecovered. Which readings of it are the ones its own numbers support?', '["No payback and an IRR of 0, since a pool that never clears is capital that never comes home.", "Payback in year 3 and an IRR of 0, because the engine suppresses a rate whenever the pool is still open.", "No payback and an IRR of 54.6792 percent, since a positive rate can be reported without a crossing.", "Payback in year 3, payout in year 2 and an IRR of 54.6792 percent, on a life contractor total of 1530.0622."]'::jsonb, 3, 'At a 5 percent limit almost nothing comes back as cost oil, but the revenue that cannot be recovered becomes profit oil, and this regime splits it 100 percent to the contractor.'),
  ('fiscal', 'beginner', 'final', null, 29, 'Payback and payout are two clocks on one ledger. What does each one measure?', '["Payback is the first year the unrecovered pool closes at 0.0000, and payout the first year profit oil is positive.", "Payback is the first year cumulative contractor net cash flow is above zero, and payout the first year the R factor is above 1.0.", "Payback is measured on the contractor''s cash and payout on the state''s, so the two together bracket the project.", "Payback is the undiscounted crossing and payout the same crossing taken at the project''s discount rate."]'::jsonb, 1, 'Both are null when the event never happens, and on the default project PIA and Angola report payback 4 against payout 3.'),
  ('fiscal', 'beginner', 'final', null, 30, 'Run six templates on the default project and total revenue reads 2686.9277 on every line. What does that constant make possible?', '["It makes the whole of the spread in the answer attributable to the regime and to nothing else.", "It makes the six ledgers comparable with the test project''s 7001.1938.", "It makes the cost recovery totals comparable, since a constant revenue means a constant recoverable pool.", "It makes the government take rankable by royalty rate, since the base of the royalty is the same in each."]'::jsonb, 0, 'A fiscal regime prices barrels, it does not produce them. Contractor cash ranges from 406.2057 to 986.7327 against that identical sales figure.'),
  ('fiscal', 'beginner', 'final', null, 31, 'On the default project cost recovered totals 941.4436 under all six templates, and on the Suite test project it does not. What changed?', '["The test project has one stream instead of three, so the boe the recovery machinery works on is smaller.", "The test project''s higher revenue lifts every ceiling above the costs, so each template recovers a different amount early.", "No pool empties inside the test project''s life, so the closing balances run from 72.7082 to 251.6537 and the recovered totals differ.", "The test project''s capex of 1000 is larger than its life opex, which the recovery machinery treats differently."]'::jsonb, 2, 'Cost the ledger never assigned to cost oil is cost the contractor still paid, and the totals row is where that shows.'),
  ('fiscal', 'beginner', 'final', null, 32, 'ODIDI closes its cumulative in the black under all six templates and returns a negative value under all six at the project''s 12 percent. What is the reading?', '["The value and the cumulative disagree because the value excludes the year 1 capex of 420.0000.", "The field returns its nominal money and is still not worth building at the rate it is discounted at.", "The field is worth building under the templates whose cumulative is largest, which the value fails to rank.", "The negative values are an artefact of the fixed 25 year horizon cutting the life short."]'::jsonb, 1, 'Brazil ends with 192.9896 of cash and a value of -5.8662, and Angola with 109.1947 and -58.1813.'),
  ('fiscal', 'beginner', 'final', null, 33, 'Under PIA the government share of ODIDI stays inside a band from 75.1077 to 79.4678 across nine price points, where another template gives up tens of percentage points across the same range. What does one run at one deck tell you about that difference?', '["The ranking at the base price, which the sweep then preserves at every other price it visits.", "The direction of the movement, since a regime with the higher take at one price gives up more of it as prices climb.", "The size of the movement, which is proportional to the royalty rate the template carries.", "Nothing, because one run is one deck and the shape of a regime across prices is not in a single ledger."]'::jsonb, 3, 'Two regimes that look similar on one run behave nothing alike on the next, and the same holds for a cost overrun.'),
  ('fiscal', 'beginner', 'final', null, 34, 'ODIDI''s year 1 under the Gulf of Mexico terms sells 139.6563 and spends 420.0000 of capex and 25.0037 of opex. What does the state collect that year?', '["26.1856, all of it royalty, charged on gross revenue in the year the whole of the capital was spent.", "0.0000, because the year''s residual is nothing and there is no profit oil for the state to share.", "26.1856 of royalty less the state''s share of the year''s opex, which the recovery machinery credits back.", "10.4742, which is the 7.5 percent the PIA slider charges at a deck price of 45 USD per bbl."]'::jsonb, 0, 'Royalty comes off gross revenue before any cost is considered, and revenue after royalty for the year is 113.4707.'),
  ('fiscal', 'beginner', 'final', null, 35, 'ODIDI''s gross revenue is 76.1939 in year 5 and 93.9859 in year 6, while the default project''s falls from 197.5024 in year 4 to 191.1513 in year 5. Both fields step their deck. Why do the two steps land differently?', '["ODIDI''s step arrives a year later in the life, at year 6 rather than at year 5, by which time the decline has already taken most of what it is ever going to take.", "The default project''s step at year 5 moves the gas price to 4 and the NGL price to 35 and leaves the oil price alone, so its oil revenue keeps falling straight through.", "ODIDI''s step from 45 to 65 USD per bbl outruns a 14 percent oil decline, and the default project''s step from 70 to 75 does not outrun a 10 percent decline.", "ODIDI''s three streams decline at rates far closer together, so its revenue tracks the deck more faithfully."]'::jsonb, 2, 'Same mechanism, opposite sign. Whether the jump wins depends on the size of the step against the size of the decline.'),
  ('fiscal', 'beginner', 'final', null, 36, 'The Designer''s own field empties its cost pool in year 3 under the Gulf of Mexico terms and closes the life at 0.0000, while the teaching field empties its own and then closes the life with 24.2824 unrecovered, at the same 100 percent limit. What differs?', '["Its cost recovery limit of 100 percent is reached in every one of its 25 years, where the other field''s stops binding altogether once the standing pool has cleared in year 3.", "The teaching field declines 14 percent a year, so late revenue after royalty of 5.6128 no longer covers opex of 12.3405 and the pool refills.", "Its capex of 420.0000 is smaller than the 500.0000 of the other field, and a smaller pool takes longer to clear.", "Its cash flows are discounted at 12 percent rather than 10, and the pool is carried forward at the project rate."]'::jsonb, 1, 'A full limit is a ceiling on revenue after royalty, not a promise to return the spend, and this field closes with 24.2824 unrecovered.'),
  ('fiscal', 'beginner', 'final', null, 37, 'Of the capstone method''s four checks, which one can be settled on the year 1 row on its own?', '["That the closing cumulative equals the life total of the contractor column, at 980.9313.", "That a null payback is an answer and not a gap in the table, which the published case at capex 20000 returns beside a null payout.", "That the payback year and the payout year agree, which they do in year 3 on this ledger.", "That the two takes add to gross revenue less opex less capex, which reads -259.0138 on both sides in year 1."]'::jsonb, 3, 'The row checks are the identity and the zero tax on a zero residual. The other two need the whole column.'),
  ('fiscal', 'beginner', 'final', null, 38, 'The teaching field returns a life contractor total of 148.3166 under one template and 192.9896 under another, on identical volumes and an identical deck. What does that require of a reader quoting either figure?', '["Quote the range rather than a figure, since a single template''s reading is never a property of the field.", "Quote the payout year of 6 instead, which reads the same under all six templates and so belongs to the field rather than to the terms.", "Name the regime beside every reading, because both payback years and both totals are true of the same field.", "Quote the highest of the six, since the best available terms bound what the field can be worth."]'::jsonb, 2, 'Payback in year 6 and payback in year 8 are both true of ODIDI, and a reading without its regime means nothing.'),
  ('fiscal', 'beginner', 'final', null, 39, 'The capstone method proves two rows by hand and reads the remaining twenty three. What is it blind to?', '["A tier crossing, a deck step and a pool that refills late in life, none of which appear in the two rows it proves.", "A royalty taken on the wrong base, since an error of that kind only shows itself once the cumulative column has been totalled.", "A tax charged where profit oil is 0.0000, which the year 1 row cannot reveal.", "A capex spread across the early years instead of landing whole in year 1, since the year 4 row would still balance under either treatment."]'::jsonb, 0, 'Nothing in the method discounts anything either, so ODIDI''s value of -37.3123 under those terms is invisible to it.'),
  ('fiscal', 'beginner', 'final', null, 40, 'ODIDI under Brazil returns 192.9896 of contractor cash over 25 years and a value of -5.8662 at 12 percent, on an internal rate of 11.4055 percent. Which reading is wrong?', '["The value, because a life that returns positive cash cannot be worth less than nothing.", "Neither. Both are readings of the same 25 rows, and the Associate answer quotes each with its basis.", "The total, because it adds year 25 money to year 1 money and so overstates what came back.", "The internal rate, because a rate below the discount rate cannot be reported alongside a positive total."]'::jsonb, 1, 'Which of the two a decision rests on takes a discount convention, and every one of the six templates on ODIDI shows the same pair of signs.'),
  ('fiscal', 'beginner', 'final', null, 41, 'What can the Associate reading of ODIDI, which puts the state''s collection between 232.9950 and 316.7898, not say?', '["Which template collects the most, since two collections are only comparable when the closing unrecovered pools of the two ledgers are equal.", "Which template leaves the contractor the most cash over the life of the field, which is a ranking that needs a discount convention this tier does not carry.", "How much of each collection came from royalty rather than from tax.", "Which of those splits is fair, which survives a price collapse, and which numbers on a comparison screen are measurements at all."]'::jsonb, 3, 'The contractor keeps between 109.1947 and 192.9896 across the same six templates, and stating the range is not judging it.'),
  ('fiscal', 'beginner', 'final', null, 42, 'Every template in the Associate tier was read at one setting, yet three of the six carry an instrument that moves on its own. Which are they?', '["A cost recovery limit that tightens automatically as the standing pool grows, and a minimum tax that arms itself once the residual has fallen far enough.", "A corporate rate that steps with the R factor, and a royalty that steps with cumulative production.", "A royalty keyed on the oil price and a profit split keyed on the R factor, which under PIA steps the share from 60 to 40 to 30 percent.", "A discount rate that follows the price deck from one year to the next, and a profit split that follows the closing unrecovered pool of the year before it."]'::jsonb, 2, 'The R factor is a ratio of cumulatives, so it can fall back below a threshold it passed and step the contractor''s share up again.');
